#include <iostream>

int main()
{
    int n{};
    std::cin >> n;
    for (int row{ 1 }; row <= n; ++row)
    {
        for (int star{ 0 }; star < row; ++star)
        {
            std::cout << '*';
        }
        std::cout << '\n';
    }
    return 0;
}
